namespace AIContext;

public enum SyncState
{
    InSync,
    OutOfDate,
    // None of the generated files exist yet.
    NotExported,
    // An existing file was not generated by aicontext.
    Conflict
}

// Size of what a tool loads: always-on content in every request vs. content loaded only by scope or relevance.
public sealed record TargetStatus(
    string Target,
    int FileCount,
    int AlwaysOnChars,
    int OnDemandChars,
    SyncState State,
    int AlwaysOnCharsInOtherLayout);

public static class ExportStatus
{
    // Rough rule of thumb for English text and code; real tokenizers differ per model.
    public const int CharsPerToken = 4;

    public static int EstimateTokens(int chars) => (chars + CharsPerToken - 1) / CharsPerToken;

    public static IReadOnlyList<TargetStatus> Compute(
        LoadedContext loaded,
        IReadOnlyList<string> targets,
        ExportLayout layout)
    {
        var otherLayout = layout == ExportLayout.Split ? ExportLayout.Single : ExportLayout.Split;
        var result = new List<TargetStatus>();

        foreach (var name in targets)
        {
            var target = ExportTargets.Find(name)!;
            var outputs = target.Render(loaded.Context, layout);
            var plans = ExportWriter.PlanTarget(target, loaded.BasePath, loaded.Context, layout, force: false);

            var alwaysOn = outputs[0].Content.Length;
            var onDemand = outputs.Skip(1).Sum(o => o.Content.Length);
            var otherAlwaysOn = target.Render(loaded.Context, otherLayout)[0].Content.Length;

            result.Add(new TargetStatus(name, outputs.Count, alwaysOn, onDemand, DetermineState(plans), otherAlwaysOn));
        }

        return result;
    }

    private static SyncState DetermineState(IReadOnlyList<ExportFilePlan> plans)
    {
        if (plans.Any(p => p.Status == ExportFileStatus.Conflict))
        {
            return SyncState.Conflict;
        }

        if (plans.All(p => p.Status == ExportFileStatus.Unchanged))
        {
            return SyncState.InSync;
        }

        var exportedFiles = plans.Where(p => p.Status != ExportFileStatus.Created);
        return exportedFiles.Any() ? SyncState.OutOfDate : SyncState.NotExported;
    }
}
